        private int col;

        public MazeSearchTask(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public Boolean call() throws Exception {
            // Base cases
            if (row < 0 || row >= rows || col < 0 || col >= cols || maze[row][col] == '*') {
                return false;
            }

            if (row == exitRow && col == exitCol) {
